def _steps(
    direction: Direction, key: str, out: Adjacent, into: Adjacent, proven_only: bool
) -> list[tuple[str, str]]:
    """(neighbor, via) of one entity, in domain order."""
    if direction == "upstream":
        found = [(a, f"{kind}:in:{key}", p) for kind, a, p, _ in into if kind in _CROSS]
        found += [(b, f"tested_by:out:{key}", p) for kind, b, p, _ in out if kind == "tested_by"]
    else:
        found = [(b, f"{kind}:out:{key}", p) for kind, b, p, _ in out if kind in _CROSS]
    return sorted({(n, via) for n, via, p in found if p or not proven_only})


def _roots(view: View, key: str) -> list[str]:
    """``key``, its physical descendants and, for a file, its logical modules."""
    roots, layer = [key], [key]
    while layer:
        adjacency = view.adjacency(layer, kinds=("contains",))
        layer = sorted({b for k in layer for kind, b, *_ in adjacency[k][0] if kind == "contains"})
        roots += layer
    if key.startswith("file:"):
        into = view.adjacency([key], kinds=("contains_logical",))[key][1]
        roots += sorted(a for kind, a, *_ in into if kind == "contains_logical")
    return list(dict.fromkeys(roots))


def _bfs(
    view: View, roots: list[str], direction: Direction, depth: int, limit: int, proven_only: bool
) -> tuple[dict[str, tuple[int, str]], nx.DiGraph[str], str | None]:
    import networkx as nx

    seen = set(roots)
    found: dict[str, tuple[int, str]] = {}
    graph: nx.DiGraph[str] = nx.DiGraph()
    layer, examined, level = roots, 0, 0
    while layer:
        # Keys the allowance cut are absent, so a pass never reads past its edge budget.
        adjacency = view.adjacency(layer, MAX_EDGES - examined + 1)
        steps = {k: _steps(direction, k, *adjacency[k], proven_only) for k in adjacency}
        if level == depth:
            beyond = any(n not in seen for k in steps for n, _ in steps[k])
            return found, graph, "depth" if beyond else "edges" if len(steps) < len(layer) else None
        level += 1
        upcoming: list[str] = []
        for source in layer:
            if source not in adjacency:
                return found, graph, "edges"
            examined += sum(map(len, adjacency[source]))
            for neighbor, via in steps[source]:
                if not graph.has_edge(source, neighbor):  # keep the first step's ``via``
                    graph.add_edge(source, neighbor, via=via)
                if neighbor in seen:
                    continue
                if len(found) >= limit:
                    return found, graph, "limit"
                seen.add(neighbor)
                found[neighbor] = (level, via)
                upcoming.append(neighbor)
            if examined > MAX_EDGES:
                return found, graph, "edges"
        layer = upcoming
    return found, graph, None


def walk(view: View, key: str, direction: Direction, depth: int, limit: int) -> Walk:
    import networkx as nx

    roots = _roots(view, key)
    found, graph, stopped_by = _bfs(view, roots, direction, depth, limit, False)
    proven, _, _ = _bfs(view, roots, direction, depth, limit, True)
    cyclic = {k for c in nx.strongly_connected_components(graph) if len(c) > 1 for k in c}
    hops = tuple(
        Hop(k, d, proven[k][0] if k in proven else None, via, k in cyclic)
        for k, (d, via) in sorted(found.items(), key=lambda item: (item[1][0], item[0]))
    )
    return Walk(tuple(roots), hops, stopped_by, graph)

class View:
    """A read view pinned to one sealed generation. Not thread-safe.

    Everything that can be checked without native code (manifest shape, schema,
    owner, derivation components) is checked before the database is opened. Any
    damage after that, at open or on a later read, is ``StoreCorrupt``."""

    def __init__(self, directory: Path, repo_id: str) -> None:
        try:
            manifest = json.loads((directory / "MANIFEST.json").read_bytes())
        except (OSError, ValueError) as error:
            raise StoreCorrupt(f"{directory}: unreadable manifest ({error})") from error
        if not isinstance(manifest, dict):
            raise StoreCorrupt(f"{directory}: manifest is not an object")
        if manifest.get("schema") != SCHEMA_VERSION:
            raise IncompatibleIndex(
                f"{directory}: built by store schema {manifest.get('schema')!r}; re-index"
            )
        try:
            self.snapshot = Snapshot(
                *(_text(manifest[k]) for k in ("repo_id", "snapshot_id", "derivation_id"))
            )
            self.components: dict[str, str] = dict(manifest["components"])
            self.files = {
                f[0]: FileInfo(_text(f[0]), _text(f[1]), int(f[2]), f[3], f[4], tuple(f[5]))
                for f in manifest["files"]
            }
            self.lexical_unavailable: str | None = manifest["lexical_unavailable"]
            if self.lexical_unavailable is not None:
                _text(self.lexical_unavailable)
            entities = int(manifest["rows"]["Entity"])
            self.counts = (int(manifest["entities"]), int(manifest["relations"]))
        except (KeyError, TypeError, ValueError, IndexError) as error:
            raise StoreCorrupt(f"{directory}: malformed manifest ({error!r})") from error
        if self.snapshot.repo_id != repo_id:
            raise StoreCorrupt(f"{directory}: belongs to repository {self.snapshot.repo_id}")
        if _comparable(self.components) != _comparable(components(storage_components(True))):
            raise IncompatibleIndex(f"{directory}: built by another OXIDE derivation; re-index")
        self.directory = directory
        self.manifest = manifest
        self.lexical_scorer = FTS_SCORER
        self._db: ladybug.Database | None = None
        self._conn: ladybug.Connection | None = None
        self._lexical_db: ladybug.Database | None = None
        self._lexical: ladybug.Connection | None = None
        try:
            self._db = ladybug.Database(
                str(directory / "graph.lbug"),
                read_only=True,
                buffer_pool_size=BUFFER_POOL,
                max_num_threads=1,
            )
            self._conn = ladybug.Connection(self._db)
            # An empty or foreign file opens as some other database: compare what was sealed.
            stored = _rows(self._conn, "MATCH (e:Entity) RETURN count(e)")[0][0]
            owner = [r[0] for r in _rows(self._conn, "MATCH (i:Identity) RETURN i.key")]
        except RuntimeError as error:
            self.close()
            raise StoreCorrupt(f"{directory}: unreadable database ({error})") from error
        if owner != [identity(self.snapshot)]:
            self.close()
            raise StoreCorrupt(f"{directory}: database belongs to another generation")
        if stored != entities:
            self.close()
            raise StoreCorrupt(f"{directory}: {stored} entities stored, {entities} sealed")
        if self.lexical_unavailable is None:
            try:
                self._lexical_db = ladybug.Database(
                    str(directory / "lexical.lbug"),
                    read_only=True,
                    buffer_pool_size=BUFFER_POOL,
                    max_num_threads=1,
                )
                self._lexical = ladybug.Connection(self._lexical_db)
                docs = _rows(self._lexical, "MATCH (d:Doc) RETURN count(d)")[0][0]
                owner = [r[0] for r in _rows(self._lexical, "MATCH (i:Identity) RETURN i.key")]
            except RuntimeError as error:
                self.close()
                raise StoreCorrupt(f"{directory}: unreadable lexical index ({error})") from error
            if owner != [manifest.get("lexical")] or docs != entities:
                self.close()
                raise StoreCorrupt(f"{directory}: lexical index belongs to another generation")
            extension = fts_location()
            self.lexical_unavailable = fts_unavailable(extension)
            if self.lexical_unavailable is None:
                try:
                    _rows(self._lexical, f"LOAD EXTENSION {_literal(extension)}")
                except RuntimeError as error:
                    self.lexical_unavailable = f"FTS extension did not load: {error}"

    def close(self) -> None:
        if self._lexical is not None:
            self._lexical.close()
            self._lexical = None
        if self._lexical_db is not None:
            self._lexical_db.close()
            self._lexical_db = None
        if self._conn is not None:
            self._conn.close()
            self._conn = None
        if self._db is not None:
            self._db.close()
            self._db = None

    def _query(
        self, query: str, params: dict[str, Any] | None = None, lexical: bool = False
    ) -> list[Any]:
        """A read; native failures on a sealed generation mean it is damaged."""
        conn = self._lexical if lexical else self._conn
        if conn is None:
            raise Closed(f"{self.directory}: view is closed")
        try:
            return _rows(conn, query, params)
        except RuntimeError as error:
            raise StoreCorrupt(f"{self.directory}: read failed ({error})") from error

    def facts(self) -> dict[str, Any]:
        """The parse facts sealed with this generation, by dialect and file digest; empty
        when it has none of the current format or they do not match their sealed digest. A
        cache: losing it costs a re-parse, never correctness."""
        sealed = self.manifest.get("facts")
        if not isinstance(sealed, dict) or sealed.get("format") != FACTS_FORMAT:
            return {}
        try:
            data = (self.directory / "facts.json").read_bytes()
            if digest(data) != sealed.get("digest"):
                return {}
            facts = json.loads(data)
        except (OSError, ValueError):
            return {}
        return facts if isinstance(facts, dict) else {}

    def verify_sources(self) -> None:
        """Every retained source file exists and matches its digest."""
        for info in self.files.values():
            self.source(SourceRef(info.path, 0, info.size, info.digest))

    def entities(self, keys: Iterable[str]) -> dict[str, Entity]:
        wanted = sorted(set(keys))
        if not wanted:
            return {}
        query = f"MATCH (e:Entity) WHERE e.key IN $keys RETURN {_ENTITY}"
        return {row[0]: _entity(row) for row in self._query(query, {"keys": wanted})}

    def named(self, name: str, limit: int) -> tuple[list[str], bool]:
        rows = self._query(
            f"MATCH (e:Entity) WHERE e.name = $name RETURN e.key ORDER BY e.key LIMIT {limit + 1}",
            {"name": name},
        )
        return [r[0] for r in rows[:limit]], len(rows) > limit

    def innermost(self, path: str, start: int, end: int) -> str | None:
        """The smallest declaration of ``path`` whose range contains ``[start, end)``."""
        rows = self._query(
            "MATCH (e:Entity) WHERE e.category = 'symbol' AND e.path = $path "
            "AND e.start_byte <= $start AND e.end_byte >= $stop "
            "RETURN e.key ORDER BY e.end_byte - e.start_byte, e.key LIMIT 1",
            {"path": path, "start": start, "stop": end},
        )
        return rows[0][0] if rows else None

    def lexical(self, text: str, limit: int) -> tuple[list[tuple[str, float]], bool]:
        """BM25 hits in descending score, ties by key; at most ``limit``, and whether
        more matched. Entities matching nothing are absent, never scored zero."""
        if self.lexical_unavailable is not None:
            raise OxideError(f"lexical search unavailable: {self.lexical_unavailable}")
        if not text:
            return [], False
        # A parameterized QUERY_FTS_INDEX segfaults when the binding re-runs its cached
        # prepared statement (ladybug 0.21.2, measured), so the query is a literal. Only
        # OXIDE terms reach here, and they can never close the quote.
        if not _TERMS_TEXT.fullmatch(text):
            raise ValueError(f"lexical query must be OXIDE terms, got {text!r}")
        statement = (
            f"CALL QUERY_FTS_INDEX('Doc', 'lexical', '{text}', conjunctive := false, "
            "K := 1.2, B := 0.75{top}) RETURN node.key, score ORDER BY score DESC, node.key "
            "LIMIT {n}"
        )
        # `top` spares sorting every match by key (docs/fts-footprint.md § 3) but cuts
        # ties arbitrarily: exact unless its last score reaches the limit-th; then rerun.
        wide = 10 * (limit + 1)
        rows = self._query(statement.format(top=f", top := {wide}", n=wide), lexical=True)
        if len(rows) == wide and rows[-1][1] >= rows[limit - 1][1]:
            rows = self._query(statement.format(top="", n=limit + 1), lexical=True)
        rows = rows[: limit + 1]
        for key, score in rows:
            if not (isinstance(score, float) and math.isfinite(score) and score > 0):
                raise StoreCorrupt(f"invalid lexical score {score!r} for {key}")
        return [(r[0], r[1]) for r in rows[:limit]], len(rows) > limit

    def adjacency(
        self, keys: list[str], allowance: int | None = None, kinds: tuple[str, ...] = ()
    ) -> dict[str, tuple[Adjacent, Adjacent]]:
        """Resolved and ambiguous edges of every key as ``(outgoing, incoming)`` lists of
        ``(kind, other end, proven, heuristic)``: two queries for any number of keys.
        With an ``allowance``, each direction reads at most that many rows in key order;
        keys whose edges it cut are left out, so callers see the cut and never a part.
        With ``kinds``, only edges of those kinds are read."""
        found: dict[str, tuple[Adjacent, Adjacent]] = {key: ([], []) for key in keys}
        if not keys:
            return found
        params: dict[str, Any] = {"keys": sorted(set(keys)), "kinds": list(kinds)}
        match = "MATCH (a:Entity)-[r:Rel]->(b:Entity) WHERE "
        match += "r.kind IN $kinds AND " if kinds else ""
        flags = "r.resolution = 'resolved' AND r.basis <> 'heuristic', r.basis = 'heuristic'"
        bound = "" if allowance is None else f" ORDER BY k LIMIT {max(allowance, 0) + 1}"
        out = match + f"a.key IN $keys RETURN a.key AS k, r.kind, b.key, {flags}{bound}"
        into = match + f"b.key IN $keys RETURN b.key AS k, r.kind, a.key, {flags}{bound}"
        cut: str | None = None  # the first key whose edges may be incomplete
        for direction, query in enumerate((out, into)):
            rows = self._query(query, params)
            if allowance is not None and len(rows) > allowance:
                cut = min(cut or rows[allowance][0], rows[allowance][0])
            for key, kind, other, certain, heuristic in rows:
                found[key][direction].append((kind, other, certain, heuristic))
        return found if cut is None else {k: v for k, v in found.items() if k < cut}

    def mentions(self, names: list[str], kinds: tuple[str, ...]) -> int:
        """Unresolved relations of ``kinds`` whose text is one of ``names`` or ends with
        ``.name`` or ``::name``: sites that may target them, never resolved to them."""
        if not names:
            return 0
        suffixes = sorted({f"{sep}{n}" for n in names for sep in (".", "::")})
        keys = sorted({unresolved_key(n) for n in names})
        params = {"kinds": list(kinds), "names": sorted(set(names)), "suffixes": suffixes}
        # every match shares a name's key, unless a name has odd separators: scan them all
        where = "u.key IN $keys AND " if all(_SEGMENTS.fullmatch(n) for n in names) else ""
        rows = self._query(
            f"MATCH (:Entity)-[r:Opaque]->(u:Unresolved) WHERE {where}r.kind IN $kinds AND "
            "(r.name IN $names OR any(s IN $suffixes WHERE r.name ENDS WITH s)) RETURN count(*)",
            {**params, "keys": keys},
        )
        return int(rows[0][0])

    def relations(self, key: str) -> list[Relation]:
        """Every relation touching ``key``, unresolved ones included, in derivation order."""
        columns = "r.kind, r.resolution, r.basis, r.name, r.site, r.ev_path, r.ev_start, r.ev_end"
        rows = self._query(
            "MATCH (a:Entity)-[r:Rel]->(b:Entity) WHERE a.key = $key OR b.key = $key "
            f"RETURN a.key, b.key, {columns}",
            {"key": key},
        )
        rows += self._query(
            "MATCH (a:Entity)-[r:Opaque]->(:Unresolved) WHERE a.key = $key RETURN a.key, NULL, "
            "r.kind, 'unresolved', r.basis, r.name, r.site, r.ev_path, r.ev_start, r.ev_end",
            {"key": key},
        )
        out = []
        for source, target, kind, resolution, basis, name, site, path, start, end in rows:
            evidence = SourceRef(path, start, end, self.files[path].digest) if start >= 0 else None
            relation = Relation(
                kind, source, target, resolution, basis, name or None, site, evidence
            )
            out.append(relation)
        return sorted(out, key=lambda r: (r.site, r.source, r.target or ""))

    def source(self, ref: SourceRef) -> bytes:
        """The captured bytes of ``ref.path``, verified against the pinned digest; never
        the current worktree."""
        info = self.files.get(ref.path)
        if info is None or info.digest != ref.digest:
            raise StoreCorrupt(f"{ref.path}: not in this generation at {ref.digest}")
        try:
            data = (self.directory / "source" / ref.digest.removeprefix("sha256:")).read_bytes()
        except OSError as error:
            raise StoreCorrupt(f"{ref.path}: retained source missing ({error})") from error
        if digest(data) != ref.digest:
            raise StoreCorrupt(f"{ref.path}: retained source does not match {ref.digest}")
        return data


def load_pool(size: int) -> int:
    """Buffer pool for a bulk load of ``size`` bytes; reads the module values at call time."""
    return BUFFER_POOL + LOAD_POOL_PER_BYTE * size

"""The public Python API: the stable product boundary of OXIDE v2 (ADR-0011).

``index_repository -> search -> build_context`` over persisted repository state::

    with oxide.open_repository("path/to/repo") as repo:
        repo.index()
        hits = repo.search("where failed requests are retried")
        bundle = repo.build_context("where failed requests are retried", budget=1024)
        print(bundle.payload)

Every result names the snapshot it was read from. A ``Repository`` owns its store
exclusively (a second owner, in any process, gets ``OwnershipConflict``). Calls are
serialized with automatic local filesystem updates.
"""

from __future__ import annotations

import os
import threading
import time
import weakref
from collections.abc import Callable, Iterable, Mapping
from pathlib import Path
from types import TracebackType
from typing import Any, Literal

from oxide import _index, jev
from oxide.capture import CaptureCache
from oxide.core import navigation, ordering, packing, retrieval, routing, structural
from oxide.core.retrieval import Hints
from oxide.models import (
    Closed,
    ContextBundle,
    Entity,
    EntryPoint,
    FileInfo,
    Impact,
    ImpactHop,
    IndexReport,
    InvalidArgument,
    InvalidPath,
    JudgeStatus,
    Relation,
    RouteSummary,
    SearchResult,
    Snapshot,
    StructuralResult,
)
from oxide.storage.fts import prepare_fts
from oxide.storage.ladybug import View, default_data_dir
from oxide.storage.store import Store
from oxide.tracking import RECONCILE_SECONDS, Tracking, serialized

# Upper bounds of caller-chosen sizes, checked before any query is built.
MAX_LIMIT = 1000
MAX_BUDGET = 1 << 20
MAX_DEPTH = 8
_MAX_OFFSET = (1 << 63) - 1  # LadybugDB INT64


def _count(name: str, value: object, high: int) -> int:
    if isinstance(value, bool) or not isinstance(value, int) or not 0 <= value <= high:
        raise InvalidArgument(f"{name} must be an integer in [0, {high}], got {value!r}")
    return value


def _texts(name: str, values: Iterable[str]) -> tuple[str, ...]:
    try:
        out = () if isinstance(values, str) else tuple(values)
    except TypeError:
        out = None
    if out is None or isinstance(values, str) or not all(isinstance(v, str) for v in out):
        raise InvalidArgument(f"{name} must be an iterable of strings, got {values!r}")
    return out


def _hints(
    query: str,
    paths: Iterable[str],
    symbols: Iterable[str],
    selection: tuple[str, int, int] | None,
    changed: Iterable[str],
) -> Hints:
    if not isinstance(query, str):
        raise InvalidArgument(f"query must be a string, got {query!r}")
    if selection is not None:
        if not (isinstance(selection, tuple) and len(selection) == 3):
            raise InvalidArgument(f"selection must be (path, start, end), got {selection!r}")
        path, start, end = selection
        _texts("selection path", [path])
        if _count("selection start", start, _MAX_OFFSET) > _count(
            "selection end", end, _MAX_OFFSET
        ):
            raise InvalidArgument(f"selection start {start} is after its end {end}")
    seed_paths = _texts("paths", paths)
    seed_symbols = _texts("symbols", symbols)
    seed_changed = _texts("changed", changed)
    if not query.strip() and not (selection or seed_paths or seed_symbols or seed_changed):
        raise InvalidArgument("query is empty: give words or identifiers, or a path or symbol hint")
    return Hints(selection, seed_paths, seed_symbols, seed_changed)


class Repository:
    def __init__(
        self,
        path: str | os.PathLike[str],
        data_dir: str | os.PathLike[str] | None = None,
        create: bool = True,
    ) -> None:
        try:
            root = Path(path).resolve(strict=True)
        except OSError as error:
            raise InvalidPath(f"{path}: {error.strerror}") from error
        if not root.is_dir():
            raise InvalidPath(f"{root}: not a directory")
        self.root = root
        data = Path(data_dir or default_data_dir()).absolute()
        self._store: Store | None = Store(root, data, create)
        self._lock = threading.RLock()
        self._cache: CaptureCache = {}
        self._active = False
        self._tracking = Tracking(self, data)
        self._finalizer = weakref.finalize(self, self._tracking.close)

    def __enter__(self) -> Repository:
        return self

    def __exit__(
        self,
        kind: type[BaseException] | None,
        error: BaseException | None,
        trace: TracebackType | None,
    ) -> None:
        self.close()

    def close(self) -> None:
        self._tracking.stop.set()
        with self._lock:
            if self._store is not None:
                self._store.close()
                self._store = None
                self._cache.clear()
        self._tracking.close()
        self._finalizer.detach()

    @property
    def store(self) -> Store:
        if self._store is None:
            raise Closed(f"{self.root}: repository is closed")
        return self._store

    @property
    def repo_id(self) -> str:
        return self.store.repo_id

    @serialized
    def index(self, *, progress: Callable[[str], None] | None = None) -> IndexReport:
        """Fully reconcile captured bytes and publish atomically, reusing unchanged parse facts."""
        return self._index(True, progress, rehash=True)

    def _index(
        self, full: bool, progress: Callable[[str], None] | None = None, *, rehash: bool = False
    ) -> IndexReport:
        self._tracking.dirty.clear()
        if rehash:  # periodic reconciliation only re-walks; stat keys decide which bytes to re-read
            self._cache.clear()
        try:
            report = _index.index(self.root, self.store, self._cache, progress)
        except Exception:
            self._tracking.dirty.set()
            raise
        self._active = True
        self._tracking.error = None
        if full:
            self._tracking.last_full = time.monotonic()
        return report

    @serialized
    def _update(self, full: bool, paths: tuple[str, ...] = ()) -> None:
        if self._store is not None and self._active:
            # Native events invalidate bytes even on filesystems with coarse timestamps.
            for path in paths:
                self._cache.pop(path, None)
            self._index(full)

    def _view(self) -> View:
        # Preserve explicit not-indexed, incompatible and corrupt-store failures on first read.
        self.store.view()
        full = not self._active or time.monotonic() - self._tracking.last_full >= RECONCILE_SECONDS
        if full or self._tracking.dirty.is_set() or self._tracking.failed:
            self._index(full or self._tracking.failed)
        return self.store.view()

    @property
    @serialized
    def snapshot(self) -> Snapshot:
        return self._view().snapshot

    @serialized
    def files(self) -> list[FileInfo]:
        return list(self._view().files.values())

    @serialized
    def entity(self, key: str) -> Entity | None:
        return self._view().entities([key]).get(key)

    @serialized
    def relations(self, key: str) -> list[Relation]:
        return self._view().relations(key)

    @serialized
    def impact(
        self,
        key: str,
        *,
        direction: Literal["upstream", "downstream"] = "upstream",
        depth: int = 3,
        limit: int = 200,
    ) -> Impact:
        """Bounded dependents (``upstream``) or dependencies (``downstream``) of the entity
        ``key``, nearest first, each with its proven depth. Read-only; never ranked or
