        return Impact(
            view.snapshot,
            root,
            direction,
            found.roots,
            tuple(
                ImpactHop(known[h.key], h.depth, h.proven_depth, h.via, h.cyclic)
                for h in found.hops
            ),
            view.mentions(names, ("calls", "references")) if direction == "upstream" else 0,
            found.stopped_by,
