details.oldText:
"""Reads of the ``Blast`` node table: one stored blast radius per entity (ADR-0014)."""

from __future__ import annotations

from collections.abc import Callable
from pathlib import Path
from typing import Any

from oxide.core.blast import root_from_row
from oxide.models import BlastRoot, StoreCorrupt

_QUERY = (
    "MATCH (b:Blast) WHERE b.key IN $keys RETURN b.key, b.dependents, b.tests, "
    "b.file_count, b.files, b.unresolved, b.stopped_by"
)


def read(
    query: Callable[[str, dict[str, Any]], list[Any]], directory: Path, keys: list[str]
) -> dict[str, BlastRoot]:
    """The stored blast radius of each key. Publication writes one per entity, so a
    missing key means the generation is damaged."""
    wanted = sorted(set(keys))
    if not wanted:
        return {}
    found = {row[0]: root_from_row(row) for row in query(_QUERY, {"keys": wanted})}
    if set(found) != set(wanted):
        raise StoreCorrupt(f"{directory}: no blast radius for {wanted}")
    return found

