        self._into: dict[str, list[tuple[str, str, bool, bool]]] = {}
        self._opaque: list[tuple[str, str]] = []  # (kind, name) of each unresolved edge
        self._sites: dict[str, list[int]] = {}  # name tail -> rows of ``_opaque`` it ends
